def get_async(token, url):
    resp = requests.get(url, headers={"Authorization": f"Bearer {token}", "Accept": "application/json"})
    resp.raise_for_status()
    return resp.json()

def extract_token_from_response(response):
    if response.ok:
        data = response.json()
        return data.get("token") or data.get("access_token") or ""
    return ""

def get_stripe_token():
    key = os.environ.get("STRIPE_TEST_KEY")
    if not key:
        raise RuntimeError("Set the STRIPE_TEST_KEY environment variable to your Stripe test secret key.")
    return key

def extract_field_from_response(response, field_path):
    data = response.json()
    for part in field_path.split("."):
        if isinstance(data, dict):
            data = data.get(part)
        else:
            return ""
    return "" if data is None else str(data)

def delete_by_param_async(token, url_template, value):
    url = re.sub(r"\{[^}]+\}", urllib.parse.quote(value, safe=""), url_template, count=1)
    return requests.delete(url, headers={"Authorization": f"Bearer {token}", "Accept": "application/json"})

def post_multipart_async(token, url, file_path, file_field_name):
    with open(file_path, "rb") as fh:
        files = {file_field_name: (os.path.basename(file_path), fh)}
        return requests.post(url, headers={"Authorization": f"Bearer {token}", "Accept": "application/json"}, files=files)
